BUDGET = {'input': 8000, 'output': 1000, 'daily_user': 100000}
usage = {'daily_user': 0}

def send(prompt_tokens, max_out):
    if prompt_tokens > BUDGET['input']:
        return 'REJECT: input %d > budget %d (retrieve smarter)' % (prompt_tokens, BUDGET['input'])
    if usage['daily_user'] + prompt_tokens > BUDGET['daily_user']:
        return 'REJECT: daily budget exhausted'
    usage['daily_user'] += prompt_tokens
    return 'sent (%d tokens), daily used %d/%d' % (prompt_tokens, usage['daily_user'], BUDGET['daily_user'])

print(send(5000, 500))
print(send(20000, 500))
print('budgets turn efficiency from advice into architecture')

TEMPLATES = {
    'v3': 'Summarize in one sentence: {text}',
    'v4': '<task>Summarize in one sentence.</task>\n<text>{text}</text>\n<output>{{"summary": "..."}}</output>',
}

def render(version, **kw):
    return TEMPLATES[version].format(**kw)

print(render('v4', text='The quick brown fox...')[:80], '...')
print('versioned like code; A/B on evals; token cost predictable (template is constant)')

