# prefill (parallel) vs decode (serial): the latency asymmetry
def prefill_ms(tokens):
    return tokens * 0.02      # parallel: 0.02ms/token

def decode_ms(tokens):
    return tokens * 25        # serial: 25ms/token

for inp, out in ((2000, 200), (20000, 200), (2000, 2000)):
    print('in=%5d out=%4d -> prefill %4.0fms + decode %5.0fms = %5.0fms' %
          (inp, out, prefill_ms(inp), decode_ms(out), prefill_ms(inp) + decode_ms(out)))
print('shaping inputs cuts prefill; capping outputs cuts decode: different levers')

import json

def guarded_call(prompt_tokens, full_tokens):
    # try compressed; validate; fall back to full on failure
    out = '{"summary": "ok"}'  # simulated compressed-prompt output
    try:
        data = json.loads(out)
        assert 'summary' in data
        return 'compressed prompt OK (%d tokens saved)' % (full_tokens - prompt_tokens)
    except (ValueError, AssertionError):
        return 'guardrail tripped: falling back to full prompt'

print(guarded_call(2000, 20000))
print('efficiency is a dial; guardrails are the stops')
